35	/**
36	 * A Utility class for IOStatisticsContext, which helps in creating and
37	 * getting the current active context. Static methods in this class allows to
38	 * get the current context to start aggregating the IOStatistics.
39	 *
40	 * Static initializer is used to work out if the feature to collect
41	 * thread-level IOStatistics is enabled or not and the corresponding
42	 * implementation class is called for it.
43	 *
44	 * Weak Reference thread map to be used to keep track of different context's
45	 * to avoid long-lived memory leakages as these references would be cleaned
46	 * up at GC.
47	 */
48	public final class IOStatisticsContextIntegration {
49	
50	  private static final Logger LOG =
51	      LoggerFactory.getLogger(IOStatisticsContextIntegration.class);
52	
53	  /**
54	   * Is thread-level IO Statistics enabled?
55	   */
56	  private static boolean isThreadIOStatsEnabled;
57	
58	  /**
59	   * ID for next instance to create.
60	   */
61	  public static final AtomicLong INSTANCE_ID = new AtomicLong(1);
62	
63	  /**
64	   * Active IOStatistics Context containing different worker thread's
65	   * statistics. Weak Reference so that it gets cleaned up during GC and we
66	   * avoid any memory leak issues due to long lived references.
67	   */
68	  private static final WeakReferenceThreadMap<IOStatisticsContext>
69	      ACTIVE_IOSTATS_CONTEXT =
70	      new WeakReferenceThreadMap<>(
71	          IOStatisticsContextIntegration::createNewInstance,
72	          IOStatisticsContextIntegration::referenceLostContext
73	      );
74	
75	  static {
76	    // Work out if the current context has thread level IOStatistics enabled.
77	    final Configuration configuration = new Configuration();
78	    isThreadIOStatsEnabled =
79	        configuration.getBoolean(THREAD_LEVEL_IOSTATISTICS_ENABLED,
80	            THREAD_LEVEL_IOSTATISTICS_ENABLED_DEFAULT);
81	  }
82	
83	  /**
84	   * Private constructor for a utility class to be used in IOStatisticsContext.
85	   */
86	  private IOStatisticsContextIntegration() {}
87	
88	  /**
89	   * Creating a new IOStatisticsContext instance for a FS to be used.
90	   * @param key Thread ID that represents which thread the context belongs to.
91	   * @return an instance of IOStatisticsContext.
92	   */
93	  private static IOStatisticsContext createNewInstance(Long key) {
94	    return new IOStatisticsContextImpl(key, INSTANCE_ID.getAndIncrement());
95	  }
96	
97	  /**
98	   * In case of reference loss for IOStatisticsContext.
99	   * @param key ThreadID.
100	   */
101	  private static void referenceLostContext(Long key) {
102	    LOG.debug("Reference lost for threadID for the context: {}", key);
103	  }
104	
105	  /**
106	   * Get the current thread's IOStatisticsContext instance. If no instance is
107	   * present for this thread ID, create one using the factory.
108	   * @return instance of IOStatisticsContext.
109	   */
110	  public static IOStatisticsContext getCurrentIOStatisticsContext() {
111	    return isThreadIOStatsEnabled
112	        ? ACTIVE_IOSTATS_CONTEXT.getForCurrentThread()
113	        : EmptyIOStatisticsContextImpl.getInstance();
114	  }
115	
116	  /**
117	   * Set the IOStatisticsContext for the current thread.
118	   * @param statisticsContext IOStatistics context instance for the
119	   * current thread. If null, the context is reset.
120	   */
121	  public static void setThreadIOStatisticsContext(
122	      IOStatisticsContext statisticsContext) {
123	    if (isThreadIOStatsEnabled) {
124	      if (statisticsContext == null) {
125	        ACTIVE_IOSTATS_CONTEXT.removeForCurrentThread();
126	      }
127	      if (ACTIVE_IOSTATS_CONTEXT.getForCurrentThread() != statisticsContext) {
128	        ACTIVE_IOSTATS_CONTEXT.setForCurrentThread(statisticsContext);
129	      }
130	    }
131	  }
132	
133	  /**
134	   * Get thread ID specific IOStatistics values if
135	   * statistics are enabled and the thread ID is in the map.
136	   * @param testThreadId thread ID.
137	   * @return IOStatisticsContext if found in the map.
138	   */
139	  @VisibleForTesting
140	  public static IOStatisticsContext getThreadSpecificIOStatisticsContext(long testThreadId) {
141	    LOG.debug("IOStatsContext thread ID required: {}", testThreadId);
142	
143	    if (!isThreadIOStatsEnabled) {
144	      return null;
145	    }
146	    // lookup the weakRef IOStatisticsContext for the thread ID in the
147	    // ThreadMap.
148	    WeakReference<IOStatisticsContext> ioStatisticsSnapshotWeakReference =
149	        ACTIVE_IOSTATS_CONTEXT.lookup(testThreadId);
150	    if (ioStatisticsSnapshotWeakReference != null) {
151	      return ioStatisticsSnapshotWeakReference.get();
152	    }
153	    return null;
154	  }
155	
156	  /**
157	   * A method to enable IOStatisticsContext to override if set otherwise in
158	   * the configurations for tests.
159	   */
160	  @VisibleForTesting
161	  public static void enableIOStatisticsContext() {
162	    if (!isThreadIOStatsEnabled) {
163	      LOG.info("Enabling Thread IOStatistics..");
164	      isThreadIOStatsEnabled = true;
165	    }
166	  }
167	}

