 * This class is used to represent a range of bytes in a file
 * which is to be read in a single vectored read operation.
 */
@InterfaceAudience.Public
@InterfaceStability.Unstable
public interface FileRange {

  /**
   * Get the starting offset of the range.
   * @return the starting offset.
   */
  long getOffset();

  /**
   * Get the length of the range.
   * @return the length of the range.
   */
  int getLength();

  /**
   * Get the data of the range.
   * @return the data buffer of this range.
   */
  ByteBuffer getData();

  /**
   * Set the data of the range.
   * @param data the {@code ByteBuffer} which contains the data of this range.
   */
  void setData(ByteBuffer data);
}

