package org.apache.hadoop.fs;

import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

import org.apache.hadoop.classification.InterfaceAudience;
import org.apache.hadoop.classification.InterfaceStability;

/**
 * Utility class for vectored reads.
 */
@InterfaceAudience.Private
@InterfaceStability.Unstable
public final class VectoredReadUtils {

  /**
   * Validate a list of ranges (including checking for overlap) and
   * return the sorted list of ranges.
   * @param input the list of input ranges.
   * @return the sorted list of ranges.
   * @throws UnsupportedOperationException if the ranges overlap.
   */
  public static List<? extends FileRange> validateNonOverlappingAndReturnSortedRanges(
      List<? extends FileRange> input) {
    if (input.size() <= 1) {
      return input;
    }
    List<? extends FileRange> sortedRanges = sortRanges(input);
    FileRange prev = sortedRanges.get(0);
    for (int i = 1; i < sortedRanges.size(); i++) {
      FileRange current = sortedRanges.get(i);
      if (current.getOffset() < prev.getOffset() + prev.getLength()) {
        throw new UnsupportedOperationException("Overlapping ranges are not supported");
      }
      prev = current;
    }
    return sortedRanges;
  }

  /**
   * Sort the input ranges by offset.
   * @param input the list of input ranges.
   * @return the sorted list of ranges.
   */
  private static List<? extends FileRange> sortRanges(List<? extends FileRange> input) {
    return input.stream()
        .sorted(Comparator.comparingLong(FileRange::getOffset))
        .collect(Collectors.toList());
  }

  /**
   * private constructor.
   */
  private VectoredReadUtils() {
  }
}

