package org.apache.hadoop.fs;

import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.List;

import org.junit.Test;

import org.apache.hadoop.test.HadoopTestBase;
import org.apache.hadoop.test.LambdaTestUtils;

/**
 * Test behavior of {@link VectoredReadUtils}.
 */
public class TestVectoredReadUtils extends HadoopTestBase {

  private static FileRange createFileRange(long offset, int length) {
    return new FileRange() {
      private ByteBuffer data;

      @Override
      public long getOffset() {
        return offset;
      }

      @Override
      public int getLength() {
        return length;
      }

      @Override
      public ByteBuffer getData() {
        return data;
      }

      @Override
      public void setData(ByteBuffer buffer) {
        this.data = buffer;
      }
    };
  }

  /**
   * Overlapping ranges must be rejected, even when the overlapping
   * pair is not adjacent in the sorted list.
   */
  @Test
  public void testOverlappingRangesValidation() throws Exception {
    FileRange range1 = createFileRange(100, 100);
    FileRange range2 = createFileRange(150, 100);
    FileRange range3 = createFileRange(300, 100);
    List<FileRange> input = Arrays.asList(range1, range2, range3);
    LambdaTestUtils.intercept(UnsupportedOperationException.class,
        "Overlapping ranges are not supported",
        () -> VectoredReadUtils.validateNonOverlappingAndReturnSortedRanges(
            input));

    // ranges which become adjacent after sorting.
    FileRange range4 = createFileRange(400, 100);
    FileRange range5 = createFileRange(500, 100);
    FileRange range6 = createFileRange(450, 100);
    List<FileRange> input2 = Arrays.asList(range4, range5, range6);
    LambdaTestUtils.intercept(UnsupportedOperationException.class,
        "Overlapping ranges are not supported",
        () -> VectoredReadUtils.validateNonOverlappingAndReturnSortedRanges(
            input2));
  }

  /**
   * Non overlapping ranges must be returned in sorted order.
   */
  @Test
  public void testNonOverlappingRangesValidation() throws Exception {
    FileRange range1 = createFileRange(300, 100);
    FileRange range2 = createFileRange(100, 100);
    FileRange range3 = createFileRange(200, 100);
    List<FileRange> input = Arrays.asList(range1, range2, range3);
    List<? extends FileRange> sortedRanges = VectoredReadUtils
        .validateNonOverlappingAndReturnSortedRanges(input);
    assertEquals("Range list size", 3, sortedRanges.size());
    assertEquals("First range", range2, sortedRanges.get(0));
    assertEquals("Second range", range3, sortedRanges.get(1));
    assertEquals("Third range", range1, sortedRanges.get(2));

    // a single range is returned as-is.
    List<FileRange> singleRange = Arrays.asList(range1);
    assertSame("Single range input must be returned unchanged",
        singleRange,
        VectoredReadUtils.validateNonOverlappingAndReturnSortedRanges(
            singleRange));
  }
}

